"""Standalone Data Center. Uses existing guarded upload and QA endpoints."""
DATA_CENTER_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yipman · Data Center</title>
<style>
:root{--ink:#172c42;--muted:#64778b;--line:#dce5eb;--blue:#0969da;--teal:#087c72;--red:#b3263c}*{box-sizing:border-box}body{margin:0;background:#f3f6f8;color:var(--ink);font:15px/1.5 system-ui,sans-serif}button,input{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer;border:1px solid var(--line);background:white;border-radius:9px;padding:10px 16px;color:var(--ink);font-weight:650}button:disabled{opacity:.5;cursor:not-allowed}button.primary{background:var(--blue);border-color:var(--blue);color:white}a{color:var(--blue)}header{background:#102b43;color:white;padding:22px max(24px,calc((100vw - 1380px)/2));display:flex;justify-content:space-between;align-items:center;gap:20px}header strong{font-size:25px}header small{display:block;color:#b4c9d8}main{max-width:1428px;margin:auto;padding:28px 24px 60px}h1{font-size:32px;margin:0}h2{font-size:21px;margin:0 0 16px}h3{font-size:17px;margin:0 0 8px}p{margin:6px 0 16px}.muted{color:var(--muted)}.bar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:22px}.grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(320px,1fr);gap:20px;align-items:start}.panel{background:white;border:1px solid var(--line);border-radius:16px;padding:24px;margin-bottom:20px;min-width:0}.fresh{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin:22px 0}.tile{background:white;border:1px solid var(--line);border-radius:12px;padding:14px}.tile span,.metric span{display:block;font-size:12px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.5px}.tile b{display:block;font-size:18px;margin-top:5px}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:18px 0}.metric{background:#f5f8fa;border-radius:10px;padding:12px;overflow-wrap:anywhere}.metric b{display:block;margin-top:6px;font-size:17px}.badge{display:inline-block;border-radius:25px;padding:6px 12px;font-size:13px;font-weight:750;background:#eaf0f5}.bad{background:#fff0f2;color:var(--red)}.good{background:#e5f5ef;color:#116649}.warn{background:#fff5dc;color:#815800}.notice{border:1px solid var(--line);background:#f6f9fc;padding:14px;border-radius:10px;margin:12px 0;overflow-wrap:anywhere}.notice.bad{border-color:#f3bfc7;background:#fff3f4;color:var(--red)}.drop{border:2px dashed #bccfdf;border-radius:12px;padding:22px;background:#fafcfe}input[type=file]{width:100%;margin:12px 0}input[type=text]{padding:10px;border:1px solid var(--line);border-radius:8px;width:100%;margin:8px 0 14px}table{width:100%;border-collapse:collapse;text-align:left}th{font-size:12px;color:var(--muted);text-transform:uppercase}td,th{padding:12px 8px;border-bottom:1px solid var(--line);vertical-align:top;overflow-wrap:anywhere}td{font-size:14px}details{margin-top:16px}summary{cursor:pointer;font-weight:650}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f7f9;padding:14px;border-radius:10px;font-size:12px;max-height:420px;overflow:auto}.scroll{overflow:auto}.files{overflow-wrap:anywhere}.steps{display:flex;gap:6px;flex-wrap:wrap;margin-top:18px}.steps span{font-size:12px;border-radius:6px;padding:7px 10px;background:#eef2f5}.steps .done{background:#e5f5ef;color:#116649}.steps .hold{background:#fff5dc;color:#815800}#sync{font-size:12px}footer{font-size:12px;color:var(--muted);margin-top:24px}.linkbtn{border:0;background:none;padding:0;color:var(--blue);text-decoration:underline}.empty{padding:20px;color:var(--muted)}@media(max-width:950px){.grid{grid-template-columns:1fr}.fresh{grid-template-columns:repeat(3,1fr)}}@media(max-width:520px){main{padding:18px 12px}.panel{padding:18px}.metrics{grid-template-columns:repeat(2,1fr)}.fresh{grid-template-columns:repeat(2,1fr)}header{padding:16px}.bar{align-items:flex-start}h1{font-size:27px}}
</style></head><body>
<header><div><strong>Yipman</strong><small>DATA CENTER · Store #1032</small></div><div><b>FULL MYSQL</b><small id="version">Connecting…</small></div></header>
<main><div class="bar"><div><h1>Data Center</h1><p class="muted">Upload once. Track processing. Verify published data.</p><div id="sync" role="status">Loading live status…</div></div><button id="refresh">Refresh</button></div>
<div id="globalError" role="alert"></div><div id="freshness" class="fresh"></div>
<div class="grid"><div><section class="panel"><div class="bar"><h2>Batch monitor</h2><button id="follow" hidden>Follow current batch</button></div><div id="monitor" aria-live="polite">Loading current batch…</div></section>
<section class="panel"><h2>Recent batches</h2><p class="muted">Select a batch to inspect its complete run history.</p><div id="recent" class="scroll">Loading…</div></section></div>
<div><section class="panel"><h2>Upload new files</h2><p class="muted">Files selected together form one immutable batch.</p><div class="drop"><label for="files"><b>Select source files</b></label><input id="files" type="file" multiple accept=".xlsx,.xls,.xlsm,.csv,.txt,.tsv"><label for="note" class="muted">Batch note (optional)</label><input id="note" type="text" placeholder="For example: October 9 movement"><button id="upload" class="primary">Upload &amp; start processing</button></div><div id="uploadStatus" role="status" class="notice">No files uploaded in this session.</div><p class="muted">To recover an existing batch, use its monitor. Uploading again creates a separate batch.</p></section>
<section class="panel"><h2>Service health</h2><div id="health">Loading…</div></section></div></div>
<section class="panel"><h2>14-day completeness</h2><p class="muted">Completed days require canonical POS and MVT. Snapshot sources are not required daily.</p><div id="coverage" class="scroll">Loading…</div></section>
<footer>Data Center DC-1 · Live server evidence · Times shown in your browser’s local time. A healthy worker does not by itself confirm publication.</footer></main>
<script>
(()=>{'use strict';
const $=id=>document.getElementById(id), esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const metric=(k,v)=>'<div class="metric"><span>'+esc(k)+'</span><b>'+esc(v)+'</b></div>';
const parse=v=>{if(v&&typeof v==='object')return v;try{return JSON.parse(v||'{}')}catch{return {}}};
const time=v=>{if(!v)return 'Not reported';const s=String(v);const d=new Date(/Z$|[+-]\d\d:\d\d$/.test(s)?s:s+'Z');return isNaN(d)?s:d.toLocaleString()};
let selected=null,busy=false,uploading=false,resuming=false,lastSnapshot=null;
async function api(path,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),options.method?120000:20000);try{const r=await fetch(path,{...options,credentials:'same-origin',cache:'no-store',signal:controller.signal});let d;try{d=await r.json()}catch{throw Error('Server returned a non-JSON response ('+r.status+')')}if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail||d));return d}finally{clearTimeout(timer)}}
function problem(id,e){$(id).innerHTML='<div class="notice bad">Unable to load: '+esc(e.message||e)+'. Use Refresh to retry.</div>'}
function classify(b,r,detail){if(r?.processing_status==='QUEUED')return ['Queued','warn'];if(['STARTED','PAUSE_REQUESTED'].includes(r?.processing_status)){const stamp=detail.heartbeat_at;const age=stamp?(Date.now()-new Date(/Z$/.test(stamp)?stamp:stamp+'Z').getTime())/1000:null;return age===null||!Number.isFinite(age)?['Running · heartbeat unreported','warn']:age>180?['Heartbeat stale · needs review','bad']:['Processing','good']}if(['FAILED','ABORTED','FAILED_QA'].includes(r?.processing_status))return ['Failed · recovery required','bad'];if(/HOLD/.test(r?.processing_status||'')||b.processing_status==='PHASE3_QA_HOLD')return ['QA hold','warn'];if(r?.processing_status==='PAUSED')return ['Paused','warn'];if(r?.processing_status==='COMPLETED')return [b.processing_status==='QUICK_CHECK_READY_WITH_HOLDS'?'Run completed · item holds remain':'Run completed · check publication','good'];if(b.processing_status==='PHASE2C_READY')return ['Phase 2C ready · waiting for Phase 3','warn'];return [b.processing_status||'No active batch',''];}
async function inspect(id,health){const responses=await Promise.allSettled([api('/v1/web-upload/diagnostics/batch-id/'+id),api('/v1/web-upload/batches/'+id+'/qa-summary'),api('/v1/web-upload/batches/'+id+'/chatgpt-publish-status')]);if(responses[0].status!=='fulfilled'){problem('monitor',responses[0].reason);return}const d=responses[0].value,b=d.batch||{},runs=(d.runs||[]).slice().sort((a,b)=>b.pipeline_run_id-a.pipeline_run_id),pipeline=runs.filter(r=>['PHASE3_RERUN','POST_RAW_PIPELINE'].includes(r.stage_name));const r=pipeline.find(r=>['STARTED','QUEUED','PAUSE_REQUESTED'].includes(r.processing_status))||pipeline[0]||runs[0],detail=parse(r?.detail_json),qa=responses[1].status==='fulfilled'?responses[1].value:null,publish=responses[2].status==='fulfilled'?responses[2].value:null;const [label,tone]=classify(b,r,detail),active=pipeline.some(x=>['QUEUED','STARTED','PAUSE_REQUESTED'].includes(x.processing_status)),attempts=pipeline.filter(x=>x.stage_name==='PHASE3_RERUN'&&x.code_version===health?.version&&['FAILED','FAILED_QA','QA_HOLD','ABORTED','PAUSED','COMPLETED'].includes(x.processing_status)).length,canResume=!!health?.version&&b.processing_status==='PHASE2C_READY'&&!active&&attempts<3&&qa&&qa.phase3===null;lastSnapshot={diagnostics:d,qa,publish};const error=detail.error||detail.recovery_reason;
$('monitor').innerHTML='<div class="bar"><h3>Batch #'+esc(id)+'</h3><span class="badge '+tone+'">'+esc(label)+'</span></div><div class="files">'+(d.files||[]).map(f=>esc(f.original_filename)).join('<br>')+'</div><div class="metrics">'+metric('Latest / active run',r?'#'+r.pipeline_run_id:'None')+metric('Run status',r?.processing_status||'Not started')+metric('Batch state',b.processing_status)+metric('Checkpoint',detail.phase3_stage||detail.last_phase3_stage||'Not reported')+metric('Run worker',detail.worker||'Not reported')+metric('Last run heartbeat',time(detail.heartbeat_at))+metric('QA blockers',qa?.phase3?.blocking_issue_count??'Not available')+metric('Ready items',qa?.phase3?.quick_check_ready_rows??'Not available')+metric('Held items',qa?.phase3?.quick_check_hold_rows??'Not available')+metric('Source rows',b.source_row_count)+metric('Phase 2C rows',d.phase2c?.normalized_row_count)+metric('Stage progress',detail.progress_current!==undefined?detail.progress_current+' '+(detail.progress_unit||''):'Not reported')+'</div>'+(error?'<div class="notice bad"><b>Latest failure / recovery reason</b><br>'+esc(error)+'</div>':'')+'<div class="steps"><span class="'+(d.files?.length?'done':'')+'">Source stored</span><span class="'+(['PASS','READY'].includes(d.phase2c?.result_status)?'done':'')+'">Phase 2C: '+esc(d.phase2c?.result_status||'Unknown')+'</span><span>Phase 3 QA: '+esc(qa?(qa.qa_available?'Available — see result':'Not available'):'Unavailable')+'</span><span>Publish: '+esc(publish?.status||'Unknown')+'</span></div><div class="notice">'+(active?'An existing run owns this batch. No additional run will be requested.':attempts>=3?'Recovery limit reached for this worker version. Resolve the failure before retrying.':canResume?'Resume Phase 3 uses the stored Phase 2C state. No source file upload is needed.':'Review the QA and publish results below. No recovery action is available for this state.')+'</div>'+(canResume?'<button id="resume" class="primary">Resume Phase 3</button>':'')+'<div id="actionStatus" role="status"></div><details><summary>Run history · '+runs.length+' recorded runs</summary><div class="scroll"><table><thead><tr><th>Run</th><th>Stage / status</th><th>Started</th><th>Ended</th></tr></thead><tbody>'+runs.map(x=>'<tr><td>#'+esc(x.pipeline_run_id)+'</td><td>'+esc(x.stage_name)+'<br>'+esc(x.processing_status)+'</td><td>'+esc(time(x.started_at))+'</td><td>'+esc(time(x.completed_at))+'</td></tr>').join('')+'</tbody></table></div></details><details><summary>QA and publish evidence</summary><pre>'+esc(JSON.stringify({qa:qa||{error:String(responses[1].reason)},publish:publish||{error:String(responses[2].reason)}},null,2))+'</pre></details><details><summary>Full batch diagnostics</summary><button id="download">Download diagnostics</button><pre>'+esc(JSON.stringify(d,null,2))+'</pre></details>';
if($('resume'))$('resume').onclick=async()=>{if(resuming)return;resuming=true;$('resume').disabled=true;try{const result=await api('/v1/web-upload/batches/'+id+'/resume-phase3',{method:'POST',headers:{'Content-Type':'application/json'}});$('actionStatus').textContent='Server response: '+JSON.stringify(result)}catch(e){$('actionStatus').textContent=e.message}finally{resuming=false;refresh()}};
$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(lastSnapshot,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='yipman-batch-'+id+'-diagnostics.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
}
async function refresh(){if(busy||uploading||resuming)return;busy=true;$('refresh').disabled=true;try{const paths=['/healthz','/v1/web-upload/active','/v1/web-upload/recent?limit=12','/v1/yipman/header-freshness','/v1/backoffice/data-health?days=14'];const result=await Promise.allSettled(paths.map(p=>api(p)));const val=i=>result[i].status==='fulfilled'?result[i].value:null,h=val(0),a=val(1),recent=val(2),fresh=val(3),coverage=val(4);let failures=result.filter(x=>x.status==='rejected').length;
if(h){$('version').textContent='API '+h.version;$('health').innerHTML='<span class="badge '+(h.worker_healthy?'good':'bad')+'">'+esc(h.worker_state||'Unknown')+'</span><div class="metrics">'+metric('Heartbeat age',h.worker_heartbeat_age_seconds===undefined?'Unknown':h.worker_heartbeat_age_seconds+' seconds')+metric('Ready',h.worker_ready?'Yes':'No')+'</div><p class="muted">Worker '+esc(h.worker_version)+'</p>'}else problem('health',result[0].reason);
if(fresh)$('freshness').innerHTML=['POS','MVT','PRICE','OH','FRESH','FRZ'].map(k=>{const s=fresh.sources?.[k]||(coverage?.latest?.[k]?{...coverage.latest[k],state:'Latest snapshot'}:{});return '<div class="tile"><span>'+esc(k==='FRZ'?'Frozen':k==='FRESH'?'Live / Fresh':k)+'</span><b>'+esc(s.date)+'</b><small class="muted">'+esc(s.state||'Unknown')+'</small></div>'}).join('');else problem('freshness',result[3].reason);
if(recent){const rows=(recent.batches||recent.rows||[]).slice();if(a?.active_batch&&!rows.some(x=>x.batch_id===a.active_batch.batch_id))rows.unshift(a.active_batch);$('recent').innerHTML='<table><thead><tr><th>Batch</th><th>Files</th><th>Status</th><th>Ready / held</th></tr></thead><tbody>'+rows.map(x=>'<tr><td><button class="linkbtn" data-batch="'+Number(x.batch_id)+'">#'+esc(x.batch_id)+'</button></td><td>'+esc((x.files||[]).map(f=>f.original_filename).join(', ')||x.batch_label||'—')+'</td><td>'+esc(x.processing_status)+'</td><td>'+esc(x.quick_check_ready_rows)+' / '+esc(x.quick_check_hold_rows)+'</td></tr>').join('')+'</tbody></table>';if(!rows.length)$('recent').innerHTML='<div class="empty">No batches returned.</div>';document.querySelectorAll('[data-batch]').forEach(btn=>btn.onclick=()=>{selected=Number(btn.dataset.batch);$('follow').hidden=false;refresh()})}else problem('recent',result[2].reason);
if(coverage){const rows=coverage.rows||[];const cell=(x,k)=>esc(x.sources?.[k]?.status||'—');$('coverage').innerHTML='<table><thead><tr><th>Date</th><th>Day status</th><th>POS</th><th>MVT</th><th>Price</th><th>OH</th></tr></thead><tbody>'+rows.map(x=>'<tr><td>'+esc(x.date)+'</td><td>'+esc(x.overall_status)+'</td><td>'+cell(x,'POS')+'</td><td>'+cell(x,'MVT')+'</td><td>'+cell(x,'PRICE')+'</td><td>'+cell(x,'OH')+'</td></tr>').join('')+'</tbody></table>';if(!rows.length)$('coverage').innerHTML='<div class="empty">No coverage rows returned.</div>'}else problem('coverage',result[4].reason);
const bid=selected||a?.active_batch?.batch_id||a?.latest_batch?.batch_id;if(bid)await inspect(bid,h);else if(!a)problem('monitor',result[1].reason);else $('monitor').innerHTML='<div class="empty">No active or latest batch returned.</div>';$('sync').textContent=(failures?'Some panels unavailable · ':'Updated · ')+new Date().toLocaleTimeString()+' · refreshes every 15 seconds while visible';
}catch(e){problem('globalError',e)}finally{busy=false;$('refresh').disabled=false}}
$('refresh').onclick=refresh;$('follow').onclick=()=>{selected=null;$('follow').hidden=true;refresh()};
$('upload').onclick=async()=>{if(uploading)return;const files=[...$('files').files];if(!files.length){$('uploadStatus').textContent='Select at least one source file.';return}uploading=true;$('upload').disabled=true;$('files').disabled=true;let created=null;try{created=await api('/v1/web-upload/batches',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({label:$('note').value.trim()||'Data Center '+new Date().toLocaleString()})});const session=created.session_id||created.batch_key||created.session?.session_id;if(!session)throw Error('No upload session returned. Inspect recent batches before trying again.');for(let i=0;i<files.length;i++){const fd=new FormData();fd.append('file',files[i]);$('uploadStatus').textContent='Uploading '+(i+1)+' / '+files.length+': '+files[i].name;await api('/v1/web-upload/batches/'+encodeURIComponent(session)+'/files',{method:'POST',body:fd})}$('uploadStatus').textContent='Committing batch…';const done=await api('/v1/web-upload/batches/'+encodeURIComponent(session)+'/commit',{method:'POST'});selected=done.batch_id||created.batch_id||null;$('follow').hidden=!selected;$('uploadStatus').textContent='Batch #'+(selected||'—')+' committed. Processing and QA are tracked in the monitor.';$('files').value=''}catch(e){$('uploadStatus').textContent='Upload stopped: '+e.message+(created?' Batch/session was created. Inspect recent batches before uploading again.':' No successful creation response received; check recent batches before retrying.')}finally{uploading=false;$('files').disabled=false;$('upload').disabled=!!created&&!!$('files').files.length;refresh()}};
refresh();setInterval(()=>{if(!document.hidden&&!document.querySelector('#monitor details[open]'))refresh()},15000);
})();
</script></body></html>'''
